{"cards": [{"node_code": "N_b6943201192bbadb", "definition": "研究汽车中使用的塑料、橡胶、纤维及涂层等高分子材料的性能、改性技术、成型工艺及在汽车部件中的应用。", "boundary": "本节点聚焦于单一或混合高分子基体材料。边界在于区分“高分子材料”与“复合材料”（若以高分子为基体增强，归复合材料；若为纯高分子或橡胶制品，归本节点）、“材料”与“工艺”（侧重材料配方与性能，成型模具设计归工艺）。", "includes": ["工程塑料、热塑性弹性体、汽车用橡胶及密封材料", "高分子材料的改性、老化性能及在汽车内饰/外饰中的应用", "汽车用涂料、胶粘剂及薄膜材料"], "excludes": ["以金属或陶瓷为基体的复合材料", "高分子材料的具体注塑/挤出模具结构设计"], "sibling_distinctions": [{"other_code": "N_e6c60ab5cfdcdf82", "rule": "高分子材料侧重单一高分子基体或橡胶制品；复合材料侧重两种及以上不同材料（如纤维+树脂）的复合结构。"}, {"other_code": "N_e1b1e4e54a4061a8", "rule": "高分子材料为非金属材料，黑色金属为铁基材料，二者材质属性完全不同。"}], "cross_boundary_rule": "若内容涉及“碳纤维增强塑料（CFRP）”，主挂载复合材料；若涉及“纯聚氨酯泡沫”，主挂载高分子材料。"}, {"node_code": "N_e6c60ab5cfdcdf82", "definition": "研究由两种或两种以上不同材料复合而成的汽车用材料（如纤维增强塑料、夹层结构）的结构、性能及轻量化应用。", "boundary": "本节点聚焦于“复合”结构材料。边界在于区分“复合材料”与“单一高分子材料”（纯塑料归高分子）、“复合材料”与“金属陶瓷”（金属陶瓷侧重粉末冶金或陶瓷相，复合材料侧重界面结合与增强机理）。", "includes": ["纤维增强聚合物（FRP）、碳纤维复合材料在汽车车身/部件中的应用", "金属基复合材料、陶瓷基复合材料及夹层结构材料", "复合材料的界面结合、层间性能及失效分析"], "excludes": ["单一金属或单一高分子材料的性能研究", "复合材料的宏观结构设计（归结构部件）"], "sibling_distinctions": [{"other_code": "N_b6943201192bbadb", "rule": "复合材料强调多相组合（如纤维+基体）；高分子材料侧重单一高分子基体或橡胶。"}, {"other_code": "N_c6565111956b0231", "rule": "金属陶瓷材料侧重粉末冶金或陶瓷相；复合材料侧重不同材料（如纤维与树脂）的复合增强。"}], "cross_boundary_rule": "若内容涉及“玻璃纤维增强塑料”，主挂载复合材料；若涉及“纯环氧树脂”，主挂载高分子材料。"}]}
